// Target: 0x00354400 __9vm_threadPQ213script_object8instancePC13vm_executableiP15script_callback
// Exact released KS/SRC/vm_thread.cpp constructor with minimal declarations.

#define NULL 0
#define THREAD_PROFILING 1

namespace script_object
{
  class instance;
}

class vm_thread;
class region;

template<class T> class vector
{
  T* first;
  T* last;
  T* end;
public:
  vector() : first(NULL), last(NULL), end(NULL) {}
  void reserve(unsigned int);
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  vm_stack(int sa, vm_thread* thread);
  ~vm_stack();
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };
  };
};

class vm_executable
{
  char opaque[32];
  unsigned short* buffer;
public:
  const unsigned short* get_start() const { return buffer; }
};

class signal_callback
{
public:
  virtual ~signal_callback();
  virtual void spawn(void* = 0) = 0;
  void disable() { disabled = true; }
  virtual bool is_code_callback();
  virtual bool is_script_callback();
protected:
  char* parms;
  bool disabled;
  bool one_shot;
  unsigned int id;
};

class script_callback : public signal_callback
{
};

class vm_thread
{
protected:
  enum flags_t
  {
    SUSPENDED = 0x0001,
    SUSPENDABLE = 0x0002
  };

  script_object::instance* inst;
  const vm_executable* ex;
  unsigned int flags;
  vm_stack dstack;
  const unsigned short* PC;
  vector<const unsigned short*> PC_stack;
  script_library_class::function::entry_t entry;
  script_callback* my_callback;
  region* local_region;
  float camera_priority;
  static unsigned int id_counter;
  unsigned int thread_id;

public:
  vm_thread(script_object::instance* i, const vm_executable* x, int sa,
            script_callback* cb);

#if THREAD_PROFILING
  float prof_runtime;
  unsigned int prof_opcount;
#endif
};

vm_thread::vm_thread(script_object::instance* i,const vm_executable* x,int sa,script_callback* cb)
  : inst(i),
    ex(x),
    flags( vm_thread::SUSPENDABLE ),
    dstack(sa,this),
    PC(ex->get_start()),
    PC_stack(),
    entry(script_library_class::function::FIRST_ENTRY)
{
  PC_stack.reserve(8);
  local_region = NULL;
  #if THREAD_PROFILING
  prof_runtime = 0;
  prof_opcount = 0;
  #endif
  my_callback = cb;
  // by default, callback is disabled until this thread terminates
  cb->disable();
  camera_priority = 0;

  thread_id = ++id_counter;
}
